<script lang="ts">import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';import Sparkles from '@lucide/svelte/icons/sparkles';import Send from '@lucide/svelte/icons/send';export let state:WorkbenchState;let capabilities:any,question='Explain what this workload provides, what it depends on, and why Atlas believes it.',answer:any,error='',busy=false,contextId=state.snapshot().contextId,selection:any;async function load(){try{capabilities=await api('/api/intelligence/capabilities')}catch(value){error=(value as Error).message}}async function ask(){busy=true;error='';try{answer=await api('/api/intelligence/analyze',{method:'POST',body:JSON.stringify({question,contextId,selectionId:selection?.semantic?selection.id:undefined})})}catch(value){error=(value as Error).message}finally{busy=false}}onMount(()=>{void load();return state.subscribe(value=>{contextId=value.contextId;selection=value.selection})})</script>
<section class="panel intelligence-panel"><header><div><strong>Atlas intelligence</strong><span>{capabilities?.provider??'Checking provider'} · read-only</span></div><Sparkles size={16}/></header><div class="intelligence-context"><span>Context</span><b>{selection?.label??contextId}</b><small>{selection?.semantic?'Selected semantic entity':'Device overview'}</small></div>{#if capabilities&&!capabilities.health?.available}<div class="intelligence-empty"><Sparkles size={28}/><h2>Calculator is not connected</h2><p>{capabilities.health?.message}</p><code>ATLAS_CALCULATOR_URL</code></div>{:else}<label><span>Ask about this Device</span><textarea bind:value={question} maxlength="4000"></textarea></label><button class="ask" onclick={ask} disabled={busy||!question.trim()}><Send size={14}/>{busy?'Analyzing…':'Ask Calculator'}</button>{#if error}<div class="panel-error">{error}</div>{/if}{#if answer}<article class="answer"><small>{answer.provider} · {answer.authority}</small><p>{answer.answer}</p>{#if answer.citations?.length}<footer>{answer.citations.length} evidence citation{answer.citations.length===1?'':'s'}</footer>{/if}</article>{/if}{/if}</section>
<style>.intelligence-panel{overflow:auto;background:#090e13}.intelligence-panel>header>:global(svg){color:#bda4ff}.intelligence-context{display:grid;grid-template-columns:auto 1fr;gap:2px 8px;border-bottom:1px solid #24303b;padding:10px 12px}.intelligence-context span{grid-row:1/3;color:#718191;font-size:9px;text-transform:uppercase}.intelligence-context b{font-size:11px}.intelligence-context small{color:#718191;font-size:9px}.intelligence-panel label{display:grid;gap:6px;padding:12px}.intelligence-panel label span{color:#8999a9;font-size:10px}.intelligence-panel textarea{min-height:120px;resize:vertical;border:1px solid #2d3a46;border-radius:6px;background:#0d151c;padding:9px;color:#e3edf5;font:11px/1.5 inherit}.ask{display:flex;align-items:center;gap:6px;margin:0 12px 12px auto;border-radius:5px;background:#bda4ff;padding:7px 10px;color:#101017;font-size:10px;font-weight:600}.ask:disabled{opacity:.5}.intelligence-empty{display:grid;place-items:center;gap:7px;padding:40px 20px;color:#718191;text-align:center}.intelligence-empty>:global(svg){color:#bda4ff}.intelligence-empty h2{color:#d6e0e8;font-size:13px}.intelligence-empty p{font-size:10px}.intelligence-empty code{border-radius:4px;background:#151d26;padding:4px 7px;font-size:9px}.answer{margin:12px;border:1px solid #354152;border-radius:7px;background:#111923;padding:12px}.answer small,.answer footer{color:#718191;font-size:9px}.answer p{margin:8px 0;color:#dce6ee;font-size:11px;line-height:1.55}</style>
